package android.content;import java.io.*;import java.util.*;public final class Context {public final File root;public final int slot;static final Map<String,SharedPreferences> stores=new java.util.concurrent.ConcurrentHashMap<>();public Context(File root,int slot){this.root=root;this.slot=slot;}File dir(String name){File f=new File(root,"slot-"+slot+"/"+name);f.mkdirs();return f;}public File getFilesDir(){return dir("files");}public File getCacheDir(){return dir("cache");}public File getNoBackupFilesDir(){return dir("nobackup");}public String getPackageName(){return "local.pocketchat.host";}public SharedPreferences getSharedPreferences(String name,int mode){return stores.computeIfAbsent(root+"/"+slot+"/"+name,k->new SharedPreferences(new File(dir("prefs"),name+".properties")));}public ContentResolver getContentResolver(){return new ContentResolver(this);}}
